import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import java.time.Instant;

class ResourceNotFoundException extends RuntimeException {
    ResourceNotFoundException(String m) { super(m); }
}

record ApiError(Instant timestamp, int status, String message) {}

@RestControllerAdvice
class GlobalExceptionHandler {

    @ExceptionHandler(ResourceNotFoundException.class)
    ResponseEntity<ApiError> handleNotFound(ResourceNotFoundException ex) {
        var body = new ApiError(Instant.now(), 404, ex.getMessage());
        return ResponseEntity.status(HttpStatus.NOT_FOUND).body(body); // 404 + JSON
    }

    @ExceptionHandler(Exception.class) // catch-all fallback
    ResponseEntity<ApiError> handleAny(Exception ex) {
        var body = new ApiError(Instant.now(), 500, "Unexpected error");
        return ResponseEntity.internalServerError().body(body);
    }
}
```

