import org.springframework.data.jpa.repository.*;
import java.util.List;

interface PostRepository extends JpaRepository<Post, Long> {

    // BAD pattern (N+1): findAll() then post.getComments() in a loop
    //   -> 1 query for posts + 1 per post for its comments.

    // FIX 1: JOIN FETCH loads posts AND their comments in ONE query.
    @Query("SELECT DISTINCT p FROM Post p JOIN FETCH p.comments")
    List<Post> findAllWithComments();

    // FIX 2: @EntityGraph — declarative eager fetch for this query only.
    @EntityGraph(attributePaths = "comments")
    @Query("SELECT p FROM Post p")
    List<Post> findAllGraph();
}
