@Component
class PaymentGatewayHealthIndicator implements HealthIndicator {
    @Override
    public Health health() {
        boolean reachable = pingGateway();
        return reachable
            ? Health.up().withDetail("gateway", "reachable").build()
            : Health.down().withDetail("gateway", "unreachable").build(); // -> overall DOWN
    }
    private boolean pingGateway() { return true; }
}
